49	/**
50	 * 检查关键 runtime 文件是否完整。
51	 * Python embeddable 的 python.exe 没数字签名, 国内 Windows Defender / 360 / 火绒
52	 * 经常按行为规则识别为 "Trojan:Win32/Wacatac" 等误报并静默隔离。
53	 * 启动前如果文件丢了, 直接弹友好提示, 不要让用户看到神秘的 ENOENT。
54	 */
55	function verifyRuntime() {
56	  if (IS_DEV) return [];  // dev 模式跳过
57	
58	  const checks = [
59	    { file: PYTHON_EXE,                                          name: 'python.exe',     minSize: 50 * 1024,  maxSize: 500 * 1024 },
60	    { file: path.join(RUNTIME_DIR, 'python', 'python311.dll'),   name: 'python311.dll',  minSize: 1024 * 1024 },
61	    { file: path.join(RUNTIME_DIR, 'python', 'python311.zip'),   name: 'python311.zip',  minSize: 1024 * 1024 },
62	    { file: path.join(RUNTIME_DIR, 'node',   'node.exe'),        name: 'node.exe',       minSize: 10 * 1024 * 1024 },
63	  ];
64	  const issues = [];
65	  for (const c of checks) {
66	    if (!fs.existsSync(c.file)) {
67	      issues.push({ file: c.file, name: c.name, reason: '文件不存在' });
68	      continue;
69	    }
70	    try {
71	      const sz = fs.statSync(c.file).size;
72	      if (c.minSize && sz < c.minSize) {
73	        issues.push({ file: c.file, name: c.name, reason: `文件大小异常 (${sz} 字节)` });
74	      } else if (c.maxSize && sz > c.maxSize) {
75	        issues.push({ file: c.file, name: c.name, reason: `文件大小异常 (${sz} 字节)` });
76	      }
77	    } catch (e) {
78	      issues.push({ file: c.file, name: c.name, reason: `无法读取 (${e.message})` });
79	    }
80	  }
81	  return issues;
82	}
