128	let pythonProcess = null;
129	let isQuitting = false;
130	let actualPort = PORT;  // 实际使用的端口（可能因占用而变）
131	let backendStderrTail = [];  // 缓存后端最近若干行 stderr，崩溃时显示真实原因
