135	// ── 端口检测 ──
136	
137	function isPortAvailable(port) {
138	  return new Promise((resolve) => {
139	    const net = require('net');
140	    const server = net.createServer();
141	    server.once('error', () => resolve(false));
142	    server.once('listening', () => { server.close(); resolve(true); });
143	    server.listen(port, '127.0.0.1');
144	  });
145	}
146	
147	async function findAvailablePort(startPort, maxTries = 10) {
148	  for (let i = 0; i < maxTries; i++) {
149	    const port = startPort + i;
150	    if (await isPortAvailable(port)) {
151	      return port;
152	    }
153	    console.log(`[Port] ${port} is occupied, trying next...`);
154	  }
155	  // 前 maxTries 个端口全占用 → 先尝试杀掉占用 startPort 的旧 MHAgent 残留进程
156	  try {
157	    const { execSync } = require('child_process');
158	    // 找到占用 startPort 的进程并杀掉
159	    const result = execSync(`netstat -ano | findstr :${startPort}`, { encoding: 'utf-8', timeout: 5000 });
160	    const lines = result.trim().split('\n');
161	    const pids = new Set();
162	    for (const line of lines) {
163	      const parts = line.trim().split(/\s+/);
164	      const pid = parts[parts.length - 1];
165	      if (pid && pid !== '0' && parseInt(pid)) pids.add(pid);
166	    }
167	    for (const pid of pids) {
168	      try { execSync(`taskkill /F /PID ${pid}`, { stdio: 'ignore', timeout: 5000 }); } catch (e) {}
169	    }
170	    console.log(`[Port] Killed ${pids.size} processes occupying port ${startPort}`);
171	    await new Promise(r => setTimeout(r, 1000));
172	    if (await isPortAvailable(startPort)) return startPort;
173	  } catch (e) {
174	    // 杀进程失败(权限/杀软/端口是别的软件占的) → 不硬用被占端口，继续往更大范围找
175	  }
176	  // ⛔ 兜底：在更大范围(+100 起)找一个真正可用的端口，避免硬返回被占端口导致 uvicorn 起不来。
177	  //   之前的 bug：这里直接 return startPort，若该端口仍被占，后端启动即 code=1 崩溃。
178	  for (let i = 100; i < 300; i++) {
179	    const port = startPort + i;
180	    if (port > 65000) break;
181	    if (await isPortAvailable(port)) {
182	      console.log(`[Port] Fallback found available port ${port}`);
183	      return port;
184	    }
185	  }
186	  // 实在找不到（极端情况）→ 返回默认端口，让 uvicorn 报错，错误会被 stderr 捕获并显示给用户
187	  console.warn('[Port] No available port found in range, falling back to default (may fail)');
188	  return startPort;
189	}
