193	function getMiKTeXDir() {
194	  const candidates = [
195	    path.join(process.env.LOCALAPPDATA || '', 'Programs', 'MiKTeX'),
196	    'C:\\Program Files\\MiKTeX',
197	  ];
198	  for (const p of candidates) {
199	    const xelatex = path.join(p, 'miktex', 'bin', 'x64', 'xelatex.exe');
200	    if (fs.existsSync(xelatex)) return p;
201	  }
202	  return null;
203	}
