205	// MiKTeX 基础目录：只要 miktex.exe 在就算装了 basic（不要求 xelatex 已就位）
206	function getMiKTeXBaseDir() {
207	  const candidates = [
208	    path.join(process.env.LOCALAPPDATA || '', 'Programs', 'MiKTeX'),
209	    'C:\\Program Files\\MiKTeX',
210	  ];
211	  for (const p of candidates) {
212	    if (fs.existsSync(path.join(p, 'miktex', 'bin', 'x64', 'miktex.exe'))) return p;
213	  }
214	  return null;
215	}
