226	// 探测 LaTeX 状态：ready=可编译 / partial=装了 MiKTeX 但缺 xelatex / missing=没装
227	function checkLaTeXStatus() {
228	  const miktexDir = getMiKTeXDir();
229	  const hasXelatex = !!miktexDir || hasXelatexOnPath();
230	  const baseDir = getMiKTeXBaseDir();
231	  const installerAvailable = fs.existsSync(path.join(RUNTIME_DIR, 'miktex-setup.exe'));
232	  let state = 'missing';
233	  if (hasXelatex) state = 'ready';
234	  else if (baseDir) state = 'partial';
235	  return { state, hasXelatex, miktexDir: miktexDir || baseDir || null, installerAvailable };
236	}
