238	// MiKTeX 常用包（basic 装完后补齐 xelatex + 中文 + 常用宏包）
239	const MIKTEX_PACKAGES = ['xetex', 'ctex', 'xecjk', 'gbt7714', 'fontspec', 'booktabs',
240	  'float', 'hyperref', 'amsmath', 'geometry', 'fancyhdr', 'caption', 'subcaption',
241	  'multirow', 'listings', 'algorithm2e', 'pgfplots', 'xcolor', 'tcolorbox',
242	  'biblatex', 'biber', 'natbib'];
243	
244	// 补装宏包 + 打开缺包自动安装（basic 已就位时调用）。onProgress 可选。
245	// 异步跑命令（spawn，不阻塞主进程/事件循环）；无论退出码如何都在 close 时 resolve；
246	// 带超时兜底（超时 kill 掉再 resolve），保证不会永久挂起。
247	function runCmdAsync(exe, args, timeoutMs) {
248	  return new Promise((resolve) => {
249	    let done = false;
250	    const finish = () => { if (!done) { done = true; if (timer) clearTimeout(timer); resolve(); } };
251	    let child;
252	    try {
253	      child = spawn(exe, args, { windowsHide: true, stdio: 'ignore' });
254	    } catch (e) { resolve(); return; }
255	    const timer = timeoutMs ? setTimeout(() => { try { child.kill(); } catch (e) {} finish(); }, timeoutMs) : null;
256	    child.on('error', finish);
257	    child.on('close', finish);
258	  });
259	}
260	
261	// 补装宏包 + 打开缺包自动安装（basic 已就位时调用）。异步非阻塞，onProgress 可选。
262	async function installMiKTeXPackages(baseDir, onProgress) {
263	  const miktexExe = path.join(baseDir, 'miktex', 'bin', 'x64', 'miktex.exe');
264	  if (!fs.existsSync(miktexExe)) return;
265	  for (const pkg of MIKTEX_PACKAGES) {
266	    if (onProgress) onProgress(`安装宏包 ${pkg} …`);
267	    // 已装/网络波动都忽略，缺的会在编译时按需自动补
268	    await runCmdAsync(miktexExe, ['packages', 'install', pkg], 60000);
269	  }
270	  const initexmf = path.join(baseDir, 'miktex', 'bin', 'x64', 'initexmf.exe');
271	  // spawn 无 shell：[MPM]AutoInstall=1 作为单个参数传，比字符串拼接更安全
272	  await runCmdAsync(initexmf, ['--set-config-value=[MPM]AutoInstall=1'], 10000);
273	}
274	
275	// 完整安装 MiKTeX（用户点按钮时调用）。全程异步非阻塞：spawn 跑安装器 + 流式回传进度，
276	// 装完再异步补宏包。带超时兜底、防重复 finish。返回 Promise<{ok, state, message}>。
277	async function installMiKTeX(onProgress) {
278	  const setupFile = path.join(RUNTIME_DIR, 'miktex-setup.exe');
279	  if (!fs.existsSync(setupFile)) {
280	    return { ok: false, state: 'missing', message: '未找到内置安装包，请手动安装：https://miktex.org/download' };
281	  }
282	
283	  // basic 未就位才跑安装器；已就位则只补宏包
284	  if (!getMiKTeXBaseDir()) {
285	    if (onProgress) onProgress('正在安装 MiKTeX（联网下包，可能需要几分钟）…');
286	    // 安装器：不阻塞、有进度、30 分钟硬超时兜底（防卡死无限等待）
287	    await new Promise((resolve) => {
288	      let done = false;
289	      const fin = () => { if (!done) { done = true; if (timer) clearTimeout(timer); resolve(); } };
290	      let child;
291	      try {
292	        child = spawn(setupFile,
293	          ['--unattended', '--auto-install=yes', '--package-set=basic', '--paper-size=A4', '--private'],
294	          { windowsHide: true });
295	      } catch (e) { resolve(); return; }
296	      const timer = setTimeout(() => { try { child.kill(); } catch (e) {} fin(); }, 1800000);
297	      const relay = (buf) => { const s = buf.toString().trim(); if (s && onProgress) onProgress(s.split('\n').pop()); };
298	      if (child.stdout) child.stdout.on('data', relay);
299	      if (child.stderr) child.stderr.on('data', relay);
300	      child.on('error', fin);   // spawn 失败也按实际落地状态判定
301	      child.on('close', fin);   // 退出码非 0 不直接判死，以 miktex.exe 是否落地为准（fin 防重复）
302	    });
303	  } else if (onProgress) {
304	    onProgress('检测到 MiKTeX 已安装，补齐宏包 …');
305	  }
306	
307	  // 装完 basic（或本就装了）→ 异步补宏包（不阻塞）
308	  const base = getMiKTeXBaseDir();
309	  if (base) { try { await installMiKTeXPackages(base, onProgress); } catch (e) {} }
310	
311	  const st = checkLaTeXStatus();
312	  return { ok: st.state !== 'missing', state: st.state,
313	    message: st.state === 'ready' ? '安装完成，论文编译已可用'
314	      : st.state === 'partial' ? 'MiKTeX 已装好，宏包将在首次编译时按需补齐'
315	      : '安装未完成，请重试或手动安装：https://miktex.org/download' };
316	}
317	
318	// 启动时的非阻塞探测：已可用则跳过；只装了 basic 缺宏包则后台补齐；
319	// 完全没装则「不弹窗、不阻塞」，交给前端红点 + 安装按钮引导（避免旧版那种"边装边弹失败"）。
320	async function ensureMiKTeX() {
321	  const st = checkLaTeXStatus();
322	  if (st.state === 'ready') { console.log('[MiKTeX] xelatex already available'); return; }
323	  if (st.state === 'partial' && st.miktexDir) {
324	    // ⛔ 后台补包，绝不 await —— 补包是异步循环，await 会拖慢启动（窗口迟迟不出）
325	    console.log('[MiKTeX] base present, installing packages in background (fire-and-forget)...');
326	    installMiKTeXPackages(st.miktexDir).catch(() => {});
327	    return;
328	  }
329	  // missing：不再启动时阻塞安装 / 不弹失败框，前端会显示红点让用户按需一键安装
330	  console.log('[MiKTeX] not installed; frontend will offer one-click install',
331	    st.installerAvailable ? '(bundled installer present)' : '(no bundled installer)');
332	}
