334	// ── Python 后端 ──
335	
336	// ⛔ 安全自愈：删除后端 services/ 与 routers/ 下残留的 Cython 中间产物 .c
337	//    以及与 .pyd 同名的 .py（编译成功后源码不该再共存）。
338	//    背景：历史版本因 Cython 编译静默降级，把内嵌完整 Python 源码的 .c 和可反编译的
339	//    .pyc/.py 一起打进了包。增量更新用 robocopy /E（只覆盖不删旧文件），单靠 manifest
340	//    删不掉用户机器上已有的 .c 残留，故在后端启动前（无文件占用）主动清理。
341	//    IS_DEV 下跳过，避免误删开发目录里正常的 .c/.py。
342	function cleanupLeakedBackendSources() {
343	  if (IS_DEV) return;
344	  const dirs = [
345	    path.join(BACKEND_DIR, 'services'),
346	    path.join(BACKEND_DIR, 'routers'),
347	  ];
348	  for (const dir of dirs) {
349	    let entries;
350	    try {
351	      entries = fs.readdirSync(dir);
352	    } catch {
353	      continue; // 目录不存在就跳过
354	    }
355	    // 该目录下所有 .pyd 对应的模块名（去掉 .cp311-win_amd64 等 ABI 后缀）
356	    const pydModules = new Set();
357	    for (const name of entries) {
358	      if (name.endsWith('.pyd')) {
359	        pydModules.add(name.replace(/\.cp\d+-[^.]+\.pyd$/i, '').replace(/\.pyd$/i, ''));
360	      }
361	    }
362	    for (const name of entries) {
363	      const full = path.join(dir, name);
364	      let del = false;
365	      // 1. 所有 .c 一律删（Cython 中间产物，正常运行目录不该有，内嵌源码）
366	      if (name.endsWith('.c')) {
367	        del = true;
368	      }
369	      // 2. 与某个 .pyd 同名的 .py（编译已生效，源码不该再共存被反编译）
370	      else if (name.endsWith('.py') && pydModules.has(name.slice(0, -3))) {
371	        del = true;
372	      }
373	      if (del) {
374	        try {
375	          fs.unlinkSync(full);
376	          console.log(`[Cleanup] removed leaked source: ${full}`);
377	        } catch (e) {
378	          console.warn(`[Cleanup] failed to remove ${full}: ${e.message}`);
379	        }
380	      }
381	    }
382	  }
383	}
