385	function startBackend() {
386	  // 查找可用的 Python
387	  let pythonPath;
388	  let pythonArgs;
389	  if (fs.existsSync(PYTHON_EXE)) {
390	    pythonPath = PYTHON_EXE;
391	    pythonArgs = ['-m', 'uvicorn', 'main:app', '--host', '127.0.0.1', '--port', String(actualPort), '--log-level', 'info'];
392	  } else {
393	    // 开发模式：按优先级查找可用 Python
394	    const candidates = [
395	      'C:\\Windows\\py.exe',                    // Windows Launcher
396	      path.join(process.env.LOCALAPPDATA || '', 'Programs', 'Python', 'Python313', 'python.exe'),
