541	function waitForBackend(maxRetries = 60, interval = 500) {
542	  return new Promise((resolve, reject) => {
543	    let attempts = 0;
544	    const healthUrl = `http://127.0.0.1:${actualPort}/api/health`;
545	    const check = () => {
546	      // 后端进程已崩溃退出 → 立即失败，不用干等满 maxRetries；崩溃原因由 exit 弹窗负责显示
547	      if (backendExited) {
548	        reject(new Error('backend process exited during startup'));
549	        return;
550	      }
551	      attempts++;
552	      const req = http.get(healthUrl, (res) => {
553	        if (res.statusCode === 200) {
554	          resolve();
555	        } else if (attempts < maxRetries) {
556	          setTimeout(check, interval);
557	        } else {
558	          reject(new Error(`Backend not ready after ${maxRetries} attempts`));
559	        }
560	      });
561	      req.on('error', () => {
562	        if (attempts < maxRetries) {
563	          setTimeout(check, interval);
564	        } else {
565	          reject(new Error(`Backend not ready after ${maxRetries} attempts`));
566	        }
567	      });
568	      req.setTimeout(2000, () => { req.destroy(); });
569	    };
570	    check();
571	  });
572	}
