759	// 启动后端前的完整性自愈（见 app.on('ready') 里的调用说明）。
760	// 带 8 秒硬超时：断网/服务器慢时不拖慢正常启动。
761	async function healBeforeBackend() {
762	  if (IS_DEV) return;  // 开发模式跑源码，无更新概念
763	  const { cfg, currentVersion } = _loadUpdateConfig();
764	  if (!cfg.server_url || cfg.server_url === 'https://update.example.com') return;
765	
766	  const healer = new Updater({
767	    server_url: cfg.server_url,
768	    install_dir: path.dirname(process.resourcesPath),
769	    current_version: currentVersion,
770	    check_interval_hours: cfg.check_interval_hours,
771	    user_data_dir: app.getPath('userData'),
772	  });
773	
774	  // ⛔ 超时从 8s 提到 90s：这是最后一道"半吊子状态"兜底防线，不能中途被打断。
775	  //   之前 8s 会把"正在下载修复漏网 .pyc"的过程切断 → 后端仍加载旧 .pyc → 人文社科 400。
776	  //   常见情况(文件全同步)verifyAndHeal 约 1s 内返回，90s 只在"真有文件要修复"时才用到，
777	  //   且内部各网络操作自带超时(manifest 10s / 每文件 60s×3 重试)，不会真正卡满 90s。
778	  let _healTimer = null;
779	  const timeout = new Promise((resolve) => {
780	    _healTimer = setTimeout(() => {
781	      // ⛔ 超时后必须中止 verifyAndHeal 的下载循环 (它有 if(this.aborted) break)，
782	      //   否则它会在后台继续 rename 覆盖 installDir 里的文件——而此时后端 python
783	      //   已启动并可能正在加载这些 .pyc，变成新的运行期占用竞态。置 aborted 让它尽快停。
784	      try { healer.aborted = true; if (typeof healer.abortDownload === 'function') healer.abortDownload(); } catch (_) {}
785	      resolve({ ok: false, reason: 'timeout(90s)' });
786	    }, 90000);
787	  });
788	  let result;
789	  try {
790	    result = await Promise.race([healer.verifyAndHeal(), timeout]);
791	  } catch (e) {
792	    console.error('[Heal] verifyAndHeal 异常(忽略，照常启动):', e && e.message);
793	    return;
794	  } finally {
795	    if (_healTimer) clearTimeout(_healTimer);
796	  }
797	  if (result && result.healed > 0) {
798	    console.log(`[Heal] 修复了 ${result.healed}/${result.brokenCount} 个更新残缺文件`);
799	  } else if (result && result.reason) {
800	    console.log(`[Heal] ${result.reason}`);
801	  }
802	}
